mapper.select:
SELECT A.RC_CODE, A.RC_RFILE_NO, A.RC_RITEM_NO, A.BND_TTL, A.JEMOK, A.ALL_ORG_NM, A.PRODREGDATE, B.PRODYEAR FROM CN_RITEM A JOIN ( SELECT RC_RFILE_NO, RC_RITEM_NO, MNGNO, KIKWANCODE, PRODYEAR FROM CN_ELEC_DOC WHERE TRANSFERYEAR = #{transferYear}
AND PRODYEAR = #{prodYear}
GROUP BY RC_RFILE_NO, RC_RITEM_NO, MNGNO, KIKWANCODE, PRODYEAR ) B ON A.RC_RFILE_NO = B.RC_RFILE_NO AND A.RC_RITEM_NO = B.RC_RITEM_NO
WHERE (A.LLM_POLICY_STATUS IS NULL OR A.LLM_POLICY_STATUS != 'PASS')
WHERE A.LLM_POLICY_STATUS IS NULL
ORDER BY A.RC_RFILE_NO, A.RC_RITEM_NO LIMIT #{limit} OFFSET #{offset}

SELECT A.RC_CODE, A.RC_RFILE_NO, A.RC_RITEM_NO, A.CLSS_ID, A.BND_TTL, A.JEMOK, A.ALL_ORG_NM, SUBSTRING_INDEX(A.ALL_ORG_NM, ' ', 1) AS DEPT_NM, A.PRODREGDATE, A.PRODYEAR FROM CN_RITEM A JOIN ( SELECT RC_RFILE_NO, RC_RITEM_NO, MNGNO FROM CN_ELEC_DOC WHERE TRANSFERYEAR = #{transferYear} AND PRODYEAR = #{prodYear} GROUP BY RC_RFILE_NO, RC_RITEM_NO, MNGNO ) B ON A.RC_RFILE_NO = B.RC_RFILE_NO AND A.RC_RITEM_NO = B.RC_RITEM_NO
AND SUBSTRING_INDEX(A.ALL_ORG_NM, ' ', 1) IN
#{department}
ORDER BY A.RC_RFILE_NO, A.RC_RITEM_NO LIMIT #{limit} OFFSET #{offset}

SELECT A.RC_CODE, A.RC_RFILE_NO, A.RC_RITEM_NO, A.BND_TTL, A.JEMOK, A.ALL_ORG_NM, SUBSTRING_INDEX(A.ALL_ORG_NM, ' ', 1) AS DEPT_NM, A.PRODREGDATE, #{prodYear} AS PRODYEAR FROM CN_RITEM A JOIN ( SELECT RC_RFILE_NO, RC_RITEM_NO FROM CN_ELEC_DOC WHERE TRANSFERYEAR = #{transferYear} AND PRODYEAR = #{prodYear} GROUP BY RC_RFILE_NO, RC_RITEM_NO ) B ON A.RC_RFILE_NO = B.RC_RFILE_NO AND A.RC_RITEM_NO = B.RC_RITEM_NO WHERE SUBSTRING_INDEX(A.ALL_ORG_NM, ' ', 1) IN
#{department}
ORDER BY A.RC_RFILE_NO, A.RC_RITEM_NO LIMIT #{limit} OFFSET #{offset}

SELECT MIN(A.RC_CODE) AS RC_CODE, A.RC_RFILE_NO, MIN(A.BND_TTL) AS BND_TTL, MIN(A.ALL_ORG_NM) AS ALL_ORG_NM, SUBSTRING_INDEX(MIN(A.ALL_ORG_NM), ' ', 1) AS DEPT_NM, #{prodYear} AS PRODYEAR FROM CN_RITEM A JOIN ( SELECT RC_RFILE_NO FROM CN_ELEC_DOC WHERE TRANSFERYEAR = #{transferYear} AND PRODYEAR = #{prodYear} GROUP BY RC_RFILE_NO ) B ON A.RC_RFILE_NO = B.RC_RFILE_NO WHERE SUBSTRING_INDEX(A.ALL_ORG_NM, ' ', 1) IN
#{department}
GROUP BY A.RC_RFILE_NO ORDER BY A.RC_RFILE_NO LIMIT #{limit} OFFSET #{offset}

SELECT A.RC_CODE, A.RC_RFILE_NO, A.RC_RITEM_NO, A.BND_TTL, A.JEMOK, A.ALL_ORG_NM, SUBSTRING_INDEX(A.ALL_ORG_NM, ' ', 1) AS DEPT_NM, A.PRODREGDATE, #{prodYear} AS PRODYEAR FROM CN_RITEM A JOIN ( SELECT RC_RFILE_NO, RC_RITEM_NO FROM CN_ELEC_DOC WHERE TRANSFERYEAR = #{transferYear} AND PRODYEAR = #{prodYear} GROUP BY RC_RFILE_NO, RC_RITEM_NO ) B ON A.RC_RFILE_NO = B.RC_RFILE_NO AND A.RC_RITEM_NO = B.RC_RITEM_NO WHERE SUBSTRING_INDEX(A.ALL_ORG_NM, ' ', 1) IN
#{department}
AND ( A.POLICY_CD IS NULL OR A.POLICY_CD = '' OR A.POLICY_NM IS NULL OR A.POLICY_NM = '해당없음' ) ORDER BY A.RC_RFILE_NO, A.RC_RITEM_NO LIMIT #{limit} OFFSET #{offset}

SELECT A.RC_CODE, A.RC_RFILE_NO, A.RC_RITEM_NO, A.BND_TTL, A.JEMOK, A.ALL_ORG_NM, SUBSTRING_INDEX(A.ALL_ORG_NM, ' ', 1) AS DEPT_NM, A.PRODREGDATE, A.PRODYEAR, A.POLICY_CD, A.LLM_POLICY_STATUS, A.LLM_POLICY_ERR_MSG, A.LLM_POLICY_UPDT FROM CN_RITEM A JOIN ( SELECT RC_RFILE_NO, RC_RITEM_NO FROM CN_ELEC_DOC WHERE TRANSFERYEAR = #{transferYear} AND PRODYEAR = #{prodYear} GROUP BY RC_RFILE_NO, RC_RITEM_NO ) B ON A.RC_RFILE_NO = B.RC_RFILE_NO AND A.RC_RITEM_NO = B.RC_RITEM_NO WHERE SUBSTRING_INDEX(A.ALL_ORG_NM, ' ', 1) IN
#{department}
AND A.POLICY_CD IS NULL AND (A.LLM_POLICY_STATUS IS NULL OR A.LLM_POLICY_STATUS != 'PASS') ORDER BY A.RC_RFILE_NO, A.RC_RITEM_NO LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE CN_RITEM
SET POLICY_CD = #{result.itemCd},
    POLICY_NM = #{result.policy},
    LLM_POLICY_STATUS = 'PASS',
    LLM_POLICY_ERR_MSG = CASE
        WHEN #{result.policy} IN ('제외', '검토 필요', '간접 관련 없음') THEN #{result.reason}
        ELSE NULL
    END,
    LLM_POLICY_UPDT = CURRENT_TIMESTAMP(3)
WHERE RC_CODE = #{target.rcCode}
  AND RC_RFILE_NO = #{target.rcRfileNo}
  AND RC_RITEM_NO = #{target.rcRitemNo}

UPDATE CN_RITEM
SET LLM_POLICY_STATUS = 'FAIL',
    LLM_POLICY_ERR_MSG = #{errorMessage},
    LLM_POLICY_UPDT = CURRENT_TIMESTAMP(3)
WHERE RC_CODE = #{target.rcCode}
  AND RC_RFILE_NO = #{target.rcRfileNo}
  AND RC_RITEM_NO = #{target.rcRitemNo}
